import {readFileSync} from 'node:fs';
import {statementCoverage, expectedStatus, coverageTier} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-status-coverage.js';
import {buildLinkIndex, readSpecFiles, corpusExists} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/lib/spec-link-index.mjs';

const spec = readFileSync('specs/hal-engine-ws-test-support/spec.md', 'utf8');
const cov = statementCoverage(spec);
const expected = expectedStatus(coverageTier(cov.testable, cov.linked));
console.log('coverage:', JSON.stringify(cov), '-> expected status:', expected);

const corpus = buildLinkIndex(readSpecFiles(process.cwd(), ['specs', 'adrs']));
const entry = corpus.get('src/transport/wsTestSupport.test.ts');
console.log('link index entry for the test file:', JSON.stringify(entry));
const linked = entry && (entry.wholeFile || entry.lines.some(l => l >= 31 && l <= 40));
console.log('require-spec-link satisfied for the it at L31:', linked === true);
console.log('corpus exists:', corpusExists(process.cwd(), ['specs','adrs']));
"

node --input-type=module -e "
import {readFileSync} from 'node:fs';
import {statementCoverage, expectedStatus, coverageTier} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-status-coverage.js';
import {segmentStatements, buildIntroOrdinals, classifyByHeuristic} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-segment.js';
import {buildLinkIndex, readSpecFiles} from './node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/lib/spec-link-index.mjs';

const spec = readFileSync('specs/hal-engine-ws-test-support/spec.md', 'utf8');
const statements = segmentStatements(spec);
const intro = buildIntroOrdinals(statements);
for (const s of statements) {
  const c = classifyByHeuristic(s, intro);
  console.log(s.ordinal, JSON.stringify(s.enclosingHeading), c.testability, JSON.stringify(s.text.slice(0, 60)));
}
const corpus = buildLinkIndex(readSpecFiles(process.cwd(), ['specs', 'adrs']));
const entry = corpus.get('src/transport/wsTestSupport.test.ts');
console.log('lines set:', entry ? [...entry.lines] : entry, 'wholeFile:', entry?.wholeFile);
"

